package com.example.rokidgeminisecretary;
import android.content.*;import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;
/** Explicit public metadata fetch. No authentication headers, installation identifiers, or APK download. */
final class LokiUpdates {
 private static final java.util.concurrent.atomic.AtomicBoolean busy=new java.util.concurrent.atomic.AtomicBoolean();
 static android.content.SharedPreferences prefs(Context c){return c.getSharedPreferences("loki-update-notices",0);}
 static JSONObject cached(Context c)throws Exception{String raw=prefs(c).getString("latest","");return raw.isEmpty()?null:new JSONObject(raw);}
 static JSONObject check(Context c)throws Exception{if(!busy.compareAndSet(false,true))throw new IOException("更新を確認中です");try{javax.net.ssl.HttpsURLConnection connection=(javax.net.ssl.HttpsURLConnection)new URL("https://api.github.com/repos/tenru-do/dennou-hisho-loki/releases?per_page=10").openConnection();connection.setConnectTimeout(8000);connection.setReadTimeout(10000);connection.setInstanceFollowRedirects(false);connection.setRequestProperty("Accept","application/vnd.github+json");connection.setRequestProperty("User-Agent","Loki-update-check");try{if(connection.getResponseCode()!=200)throw new IOException("GitHubの公開情報を取得できません。後でもう一度確認してください");ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream in=connection.getInputStream()){byte[] chunk=new byte[8192];int n;while((n=in.read(chunk))!=-1){if(bytes.size()+n>1048576)throw new IOException("更新情報が大きすぎます");bytes.write(chunk,0,n);}}JSONObject result=UpdatePolicy.parse(new JSONArray(bytes.toString("UTF-8")),System.currentTimeMillis());if(!prefs(c).edit().putString("latest",result.toString()).putLong("lastAttempt",System.currentTimeMillis()).commit())throw new IOException("更新確認の結果を保存できません");return result;}finally{connection.disconnect();}}finally{busy.set(false);}}
 static void maybeNotify(MainActivity owner){if(!prefs(owner).getBoolean("daily",false))return;long now=System.currentTimeMillis(),previous=prefs(owner).getLong("lastAttempt",0);if(now<previous||now-previous<86400000L)return;if(!prefs(owner).edit().putLong("lastAttempt",now).commit())return;new Thread(()->{try{JSONObject result=check(owner),phone=InstallationIdentity.snapshot(owner),workspace=ConversationWorkspace.snapshot(owner),glass=workspace.optBoolean("connected")?workspace.optJSONObject("installation"):null;if(UpdatePolicy.newer(result,phone,glass)&&!result.getString("tag").equals(prefs(owner).getString("notified",""))){owner.runOnUiThread(()->{if(owner.isDestroyed())return;android.widget.Toast.makeText(owner,"ロキの新しい版があります。設定の「アプリ更新・更新前チェック」で確認できます",1).show();prefs(owner).edit().putString("notified",result.optString("tag")).apply();});}}catch(Exception unavailable){/* No success badge or retry loop on failure. Manual checks retain the error. */}},"LokiUpdateNotice").start();}
 private LokiUpdates(){}
}
